import json,os,glob,datetime
TZ=datetime.timezone(datetime.timedelta(hours=8))
D='2026-11-26'
def dstr(ms):
    return datetime.datetime.fromtimestamp(ms/1000,TZ).strftime('%Y-%m-%d')
rows=[]
for fp in glob.glob('session-*.json'):
    try:
        d=json.load(open(fp,encoding='utf-8'))
        r=d.get('record',{})
        rowsx=r.get('rows',{})
        def val(k):
            return rowsx.get(k,{}).get('val')
        ident=r.get('identity',{})
        created=ident.get('createdAt')
        cd=dstr(created) if created else None
        act=val('contextActivity') or {}
        days=act.get('days',{}) or {}
        active_dates=sorted(days.keys())
        if cd!=D and D not in days: continue
        tu=val('tokenUsage') or {}
        totals=tu.get('totals',{}) or {}
        ss=val('sessionStats') or {}
        ms=val('modelSelection') or {}
        lu=ms.get('lastUsed') or {}
        cp=val('contextPressure') or {}
        td=days.get(D,{}) or {}
        cost=td.get('cost',{}) or {}
        # flatten per-day peak breakdown
        peak={}
        for prov,models in cost.items():
            for model,info in models.items():
                pk=info.get('peak',{}) if isinstance(info,dict) else {}
                for k,v in pk.items(): peak[k]=peak.get(k,0)+v
        sid=fp[len('session-'):-5]
        rows.append({
            'sid':sid,'created':cd,'active_dates':active_dates,
            'title':val('title') or '',
            'unc':totals.get('uncachedInputTokens',0),'cr':totals.get('cacheReadTokens',0),
            'out':totals.get('outputTokens',0),'cw':totals.get('cacheWriteTokens',0),
            'steps':ss.get('steps',0),'turns':ss.get('turns',0),
            'model':(lu.get('provider','')+'/'+lu.get('model','')) if lu else '',
            'window':cp.get('contextWindow',0),'pressure':cp.get('pressureTokens',0),
            'day_tokens':td.get('tokens',0),'day_peak':peak,
            'day_req':td.get('requests',0),'day_toolcalls':td.get('toolCalls',0),
        })
    except Exception as e:
        pass
json.dump(rows,open('/tmp/review_rows.json','w',encoding='utf-8'),ensure_ascii=False)
print('sessions matching D(created or active):',len(rows))
print('created on D:',sum(1 for r in rows if r['created']==D))
print('active on D:',sum(1 for r in rows if D in r['active_dates']))
print('multi-day sessions:',sum(1 for r in rows if len(r['active_dates'])>1))
PY
